import os

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException
from pydantic import AwareDatetime, BaseModel, Field

from pulso import correo, db, reloj

router = APIRouter()


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
    if not x_admin_key or x_admin_key != os.environ.get('PULSO_ADMIN_KEY'):
        raise HTTPException(401, 'Clave de administración inválida')


def ver_clase(clase):
    return dict(clase, lugares_libres=clase['cupo'] - db.confirmadas(clase['id']))


def ver_reserva(reserva):
    return {k: reserva[k] for k in ('id', 'clase_id', 'estado', 'creada')}


@router.get('/clases')
def listar_clases():
    ahora = reloj.ahora()
    return [ver_clase(c) for c in db.clases() if db.a_fecha(c['inicio']) > ahora]


@router.get('/clases/{clase_id}')
def obtener_clase(clase_id: int):
    clase = db.clase(clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    return ver_clase(clase)


class NuevaClase(BaseModel):
    nombre: str = Field(min_length=1)
    instructor: str = Field(min_length=1)
    inicio: AwareDatetime
    duracion_min: int = Field(gt=0)
    cupo: int = Field(gt=0)


@router.post('/admin/clases', status_code=201, dependencies=[Depends(admin)])
def crear_clase(datos: NuevaClase):
    return ver_clase(db.crear_clase(**datos.model_dump()))


class NuevaReserva(BaseModel):
    clase_id: int


@router.post('/reservas', status_code=201)
def reservar(datos: NuevaReserva, socio=Depends(socio_actual)):
    clase = db.clase(datos.clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    inicio = db.a_fecha(clase['inicio'])
    if inicio <= reloj.ahora():
        raise HTTPException(409, 'La clase ya empezó')
    if any(r['clase_id'] == clase['id'] and r['estado'] == 'confirmada' for r in db.reservas_de(socio['id'])):
        raise HTTPException(409, 'Ya tenés una reserva para esta clase')
    if db.confirmadas(clase['id']) >= clase['cupo']:
        raise HTTPException(409, 'La clase no tiene lugar')
    if socio['creditos'] < 1:
        raise HTTPException(409, 'No te quedan créditos')
    reserva = db.crear_reserva(socio['id'], clase['id'], reloj.ahora())
    db.sumar_creditos(socio['id'], -1)
    correo.enviar(socio['email'], f"Reserva confirmada: {clase['nombre']} el {correo.fecha_y_hora(inicio)}",
                  f"Hola {socio['nombre']}, te esperamos en {clase['nombre']} con {clase['instructor']}.")
    return ver_reserva(reserva)


@router.get('/reservas')
def mis_reservas(socio=Depends(socio_actual)):
    return [ver_reserva(r) for r in db.reservas_de(socio['id'])]


@router.get('/yo')
def yo(socio=Depends(socio_actual)):
    return {k: socio[k] for k in ('id', 'nombre', 'email', 'plan', 'creditos')}


def crear_app():
    db.inicializar()
    app = FastAPI(title='Pulso')
    app.include_router(router)
    return app
"""Acceso a la base SQLite. Las fechas se guardan como texto ISO 8601 en UTC."""
import os
import secrets
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone

ESQUEMA = """
CREATE TABLE IF NOT EXISTS socios (
    id INTEGER PRIMARY KEY,
    nombre TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    plan TEXT NOT NULL,
    creditos INTEGER NOT NULL,
    token TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS clases (
    id INTEGER PRIMARY KEY,
    nombre TEXT NOT NULL,
    instructor TEXT NOT NULL,
    inicio TEXT NOT NULL,
    duracion_min INTEGER NOT NULL,
    cupo INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS reservas (
    id INTEGER PRIMARY KEY,
    socio_id INTEGER NOT NULL REFERENCES socios(id),
    clase_id INTEGER NOT NULL REFERENCES clases(id),
    estado TEXT NOT NULL,
    creada TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS correos (
    id INTEGER PRIMARY KEY,
    para TEXT NOT NULL,
    asunto TEXT NOT NULL,
    cuerpo TEXT NOT NULL,
    creado TEXT NOT NULL
);
"""


def ruta():
    return os.environ.get('PULSO_DB', 'pulso.db')


@contextmanager
def conexion():
    con = sqlite3.connect(ruta())
    con.row_factory = sqlite3.Row
    con.execute('PRAGMA foreign_keys = ON')
    try:
        yield con
        con.commit()
    finally:
        con.close()


def inicializar():
    with conexion() as con:
        con.executescript(ESQUEMA)


def a_texto(momento):
    return momento.astimezone(timezone.utc).replace(microsecond=0).isoformat()


def a_fecha(texto):
    return datetime.fromisoformat(texto)


def _una(sql, parametros=()):
    with conexion() as con:
        fila = con.execute(sql, parametros).fetchone()
    return dict(fila) if fila else None


def _varias(sql, parametros=()):
    with conexion() as con:
        return [dict(f) for f in con.execute(sql, parametros).fetchall()]


def crear_socio(nombre, email, plan='basico', creditos=8):
    with conexion() as con:
        cur = con.execute('INSERT INTO socios (nombre, email, plan, creditos, token) VALUES (?, ?, ?, ?, ?)',
                          (nombre, email, plan, creditos, secrets.token_hex(16)))
    return socio(cur.lastrowid)


def socio(socio_id):
    return _una('SELECT * FROM socios WHERE id = ?', (socio_id,))


def socio_por_token(token):
    return _una('SELECT * FROM socios WHERE token = ?', (token,))


def crear_clase(nombre, instructor, inicio, duracion_min=60, cupo=20):
    with conexion() as con:
        cur = con.execute('INSERT INTO clases (nombre, instructor, inicio, duracion_min, cupo) VALUES (?, ?, ?, ?, ?)',
                          (nombre, instructor, a_texto(inicio), duracion_min, cupo))
    return clase(cur.lastrowid)


def clase(clase_id):
    return _una('SELECT * FROM clases WHERE id = ?', (clase_id,))


def clases():
    return _varias('SELECT * FROM clases ORDER BY inicio, id')


def confirmadas(clase_id):
    return _una("SELECT COUNT(*) AS n FROM reservas WHERE clase_id = ? AND estado = 'confirmada'", (clase_id,))['n']


def crear_reserva(socio_id, clase_id, creada, estado='confirmada'):
    with conexion() as con:
        cur = con.execute('INSERT INTO reservas (socio_id, clase_id, estado, creada) VALUES (?, ?, ?, ?)',
                          (socio_id, clase_id, estado, a_texto(creada)))
    return reserva(cur.lastrowid)


def reserva(reserva_id):
    return _una('SELECT * FROM reservas WHERE id = ?', (reserva_id,))


def reservas_de(socio_id):
    return _varias('SELECT r.* FROM reservas r JOIN clases c ON c.id = r.clase_id '
                   'WHERE r.socio_id = ? ORDER BY c.inicio, r.id', (socio_id,))


def sumar_creditos(socio_id, cantidad):
    with conexion() as con:
        con.execute('UPDATE socios SET creditos = creditos + ? WHERE id = ?', (cantidad, socio_id))


def correos():
    return _varias('SELECT * FROM correos ORDER BY id')
"""Bandeja de salida de correos. Un proceso aparte la vacía; la app solo guarda cada correo acá."""
from pulso import db, reloj


def enviar(para, asunto, cuerpo):
    with db.conexion() as con:
        con.execute('INSERT INTO correos (para, asunto, cuerpo, creado) VALUES (?, ?, ?, ?)',
                    (para, asunto, cuerpo, db.a_texto(reloj.ahora())))


def fecha_y_hora(momento):
    """Formato que usan los correos: '10/11 a las 18:30', en hora de Montevideo."""
    local = momento.astimezone(reloj.MONTEVIDEO)
    return f'{local:%d/%m} a las {local:%H:%M}'
